from lib import *
r=[]
r.append(R(6923760,"प्याज़, शैलट और जड़ी-बूटियों का फ्रिटाटा","छुट्टियों में परिवार के साथ आनंद लेने के लिए हल्का और सरल नाश्ता ढूँढ रहे हैं? यह फ्रिटाटा काम कर देगा। अगर आपकी भोजन योजना अनुमति दे, तो इसे हरी पत्तियों, साबुत गेहूँ के टोस्ट और साथ में कुछ फलों के साथ परोसें।","6","पैन का 1/6 हिस्सा",
["2 छोटे चम्मच जैतून का तेल (बाँटकर)","1 कप प्याज़ (कटा हुआ)","2 बड़े चम्मच शैलट (बारीक कटे हुए)","2 साबुत अंडे","4 साबुत अंडों की सफ़ेदी","1/4 कप ताज़ी तुलसी (बारीक कटी हुई)","2 बड़े चम्मच पारमेसन या रोमानो चीज़ (ताज़ा कसा हुआ)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। एक बड़ी नॉनस्टिक ओवन-सुरक्षित कड़ाही में मध्यम आँच पर 1 छोटा चम्मच जैतून का तेल गरम करें। प्याज़ और शैलट डालें और लगभग 7 से 8 मिनट भूनें। प्याज़ का मिश्रण कड़ाही से निकालकर एक तरफ़ रख दें।","अंडे, अंडे की सफ़ेदी, तुलसी, और नमक व काली मिर्च को फेंटें। प्याज़ के मिश्रण को धीरे से मिलाएँ।","बचे हुए 1 छोटे चम्मच तेल में, अंडे के मिश्रण को कड़ाही में मध्यम-धीमी आँच पर गरम करें। बिना चलाए लगभग 8 मिनट पकाएँ।","कड़ाही को ओवन में रखें, ऊपर से चीज़ छिड़कें और लगभग 10 मिनट तक बेक करें जब तक कि ऊपरी हिस्सा बहने वाला न रहे। ज़रूरत हो तो 5 मिनट और पकाएँ। परोसने के लिए तिकोने टुकड़ों में काट लें।"]))
r.append(R(6923905,"कद्दू के बीज","कद्दू के बीजों की पोषण संबंधी जानकारी","1","3 बड़े चम्मच",["3 बड़े चम्मच कद्दू के बीज"],[]))
r.append(R(6924449,"लहसुन वाला टमाटर सलाद","प्लम और चेरी टमाटर साल भर अच्छे लगते हैं, इसलिए आप इस सलाद का आनंद कभी भी ले सकते हैं। गर्मियों में, पीले या हीयरलूम टमाटर इस्तेमाल करने में संकोच न करें। ग्रिल्ड झींगा इस सलाद में बेहतरीन लगता है, इसलिए इसे मुख्य व्यंजन बनाना चाहें तो डाल लें। तुलसी की जगह कटी हुई पुदीने की पत्तियों के साथ आज़माएँ या आधा पुदीना और आधी तुलसी इस्तेमाल करें।","10","1 कप",
["1 बटर लेट्यूस का गोला (बड़े पत्ते छोटे टुकड़ों में फाड़े हुए)","4 छोटे रोमा (प्लम) टमाटर (या 2 बड़े, कटे हुए)","20 साबुत चेरी टमाटर (आधे कटे हुए)","1 फाँक लहसुन (बहुत बारीक कटा हुआ)","2 छोटे चम्मच रेड वाइन सिरका","1/2 छोटा चम्मच डिजॉन सरसों","2 बड़े चम्मच जैतून का तेल","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च (ताज़ी पिसी हुई)","16 पत्ते ताज़ी तुलसी (पतले कटे हुए)","1 बड़ा चम्मच कद्दू के बीज (भुने हुए)","1 बड़ा चम्मच सूरजमुखी के बीज"],
["लेट्यूस के पत्तों की एक परत परोसने वाली थाली या चार प्लेटों पर रखें और कटे हुए टमाटर सजाएँ। ऊपर चेरी टमाटर रखें।","लहसुन, सिरका, सरसों, तेल, नमक और काली मिर्च को फेंटें और टमाटरों पर डालें।","तुलसी के पत्ते और कद्दू व सूरजमुखी के बीज टमाटरों पर बिखेरें और तुरंत परोसें।"]))
r.append(R(6925171,"एयर फ्रायर बटरमिल्क फ्राइड चिकन","क्या फ्राइड चिकन को मधुमेह के अनुकूल बनाना संभव है? बिल्कुल! ख़ासकर अगर आपके पास एयर फ्रायर है। यह छोटा उपकरण गरम घूमती हवा से खाने को \"फ्राई\" करता है, इसलिए आप पारंपरिक डीप फ्राइंग की तुलना में वसा और कैलोरी के एक छोटे से हिस्से के साथ तलने जैसी कुरकुरी, खस्ता बाहरी परत बना सकते हैं। यह रेसिपी चिकन को बटरमिल्क में मैरिनेट करके, फिर कॉर्नफ्लेक्स की परत में लपेटकर रसदार, स्वादिष्ट फ्राइड चिकन बनाती है। फिर एयर फ्रायर अपना जादू दिखाता है और यह फ्राइड चिकन देता है जो कुरकुरा, नरम और स्वाद से भरपूर है! सबसे बेहतरीन दक्षिणी आरामदायक भोजन के लिए इस चिकन के ऊपर कम वसा वाली क्रीमी ग्रेवी डालें और साथ में सदर्न कोलार्ड ग्रीन्स परोसें!\n\nमधुमेह के अनुकूल और एयर फ्रायर रेसिपी चाहिए? यह लेख देखें।\n\nPowered by Homemade","4","चिकन का 1 (4 औंस) टुकड़ा",
["1/3 कप कम वसा वाला बटरमिल्क","1/4 छोटा चम्मच तीखी सॉस","1 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (लंबाई में आधे कटे हुए ताकि 4 बराबर हिस्से बनें)","6 बड़े चम्मच कॉर्न फ्लेक्स","3 बड़े चम्मच स्टोन-ग्राउंड कॉर्नमील","1 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच पेपरिका","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 स्प्रे, 0.5 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["एक छोटे, गहरे कटोरे में बटरमिल्क और तीखी सॉस को मिलाएँ। चिकन को बटरमिल्क के मिश्रण में रखें। 15 मिनट रहने दें।","कॉर्नफ्लेक्स को फ़ूड प्रोसेसर के कटोरे में डालें। मोटा चूरा बनने तक प्रोसेस करें। कॉर्नमील, लहसुन पाउडर, पेपरिका, नमक और काली मिर्च डालें और समान रूप से मिलने तक पल्स करें। चूरे को उथले कटोरे में डालें। (अगर आपके पास फ़ूड प्रोसेसर नहीं है, तो आप कॉर्नफ्लेक्स को प्लास्टिक बैग में बेलन से कुचल सकते हैं।)","चिकन का पानी निथारें, अतिरिक्त बटरमिल्क को वापस कटोरे में टपकने दें। चिकन के टुकड़ों को कॉर्नफ्लेक्स के मिश्रण में समान रूप से लपेटें। लिपटे चिकन के टुकड़ों को वायर रैक पर रखें।","चिकन को एयर फ्रायर की टोकरी में रखें। 2 सेकंड के लिए नॉनस्टिक कुकिंग स्प्रे करें (चिकन को ठूँस-ठूँसकर न रखें; अगर सारा चिकन न समाए तो खेप में पकाएँ)। तापमान 375°F पर सेट करें और 7 मिनट एयर फ्राई करें।","चिकन के टुकड़ों को पलटें। 7–10 मिनट और एयर फ्राई करें या जब तक चिकन पक न जाए और बीच में डाला गया मीट थर्मामीटर 165°F न दिखाए।"]))
r.append(R(6925458,"हरी शिमला मिर्च के साथ तिलापिया स्ट्यू","स्ट्यूड टमाटर इस मछली के स्ट्यू को आसान और स्वादिष्ट समुद्री भोजन बनाते हैं। टमाटर से बनी सॉस में मछली को पोच करने से मछली नरम रहती है।","4","1 कप",
["1 मध्यम हरी शिमला मिर्च (कटी हुई)","1 डिब्बा इतालवी मसालों वाले स्ट्यूड टमाटर (14.5 औंस)","1 कप पानी","1 पाउंड तिलापिया (धोई हुई और 1 इंच के टुकड़ों में कटी हुई)","1/2 छोटा चम्मच सीफ़ूड सीज़निंग"],
["एक बड़े सॉसपैन को मध्यम आँच पर गरम होने तक रखें। पैन पर नॉनस्टिक कुकिंग स्प्रे करें, शिमला मिर्च डालें और बार-बार चलाते हुए 5 मिनट या हल्का भूरा होना शुरू होने तक पकाएँ।","टमाटर और पानी डालें, आँच तेज़ करें और उबाल आने दें। आँच धीमी करें, कसकर ढक दें और टमाटर के नरम होने तक धीमी आँच पर पकाएँ। चम्मच के पिछले हिस्से से टमाटर के बड़े टुकड़ों को तोड़ दें।","मछली और मसाले डालें और बहुत धीरे से चलाएँ। आँच तेज़ करें और बस उबलने तक लाएँ। आँच धीमी करें, कसकर ढक दें और 3 मिनट या मछली के बीच में अपारदर्शी होने तक धीमी आँच पर पकाएँ। आँच से हटाएँ और स्वाद विकसित होने के लिए ढककर 10 मिनट रहने दें।"]))
r.append(R(6925472,"ब्लैक बीन और क्विनोआ मेसन जार सलाद","यह सलाद ताज़ी, कम वसा वाली, भूमध्यसागरीय शैली की, शाकाहारी और वीगन रेसिपी है जिसे पहले से तैयार किया जा सकता है। पौधों से मिलने वाले प्रोटीन, फ़ाइबर और सब्ज़ियों से भरपूर, और ज़ायकेदार नीबू-हरा धनिया विनेग्रेट की परतों के साथ, यह चलते-फिरते दोपहर के भोजन के लिए एकदम सही है जो रक्त शर्करा (ब्लड शुगर) को नियंत्रित करने में मदद करता है। बिना अतिरिक्त चीनी और उच्च फ़ाइबर वाले कार्बोहाइड्रेट के साथ जो धीरे पचते हैं, यह मधुमेह वाले लोगों के लिए समझदारी भरा, संतोषजनक विकल्प है।","4","1 जार",
["1 कप क्विनोआ (सूखा)","1 1/2 कप डिब्बाबंद कम सोडियम वाले काले बीन्स (पानी निथारे और धोए हुए)","1 1/2 कप चेरी टमाटर (आधे कटे हुए)","1 साबुत खीरा (कटा हुआ)","1 साबुत नारंगी शिमला मिर्च (कटी हुई)","2 कप बेबी पालक (कटा हुआ)","1/4 कप लाल प्याज़ (बारीक कटा हुआ)","1 बड़ा चम्मच हरा धनिया (कटा हुआ)","1/4 कप ताज़ा नीबू का रस","1 बड़ा चम्मच जैतून का तेल","1 छोटा चम्मच डिजॉन सरसों","1 फाँक लहसुन (बारीक कटा हुआ)","1/4 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च"],
["क्विनोआ को ठंडे पानी से धोएँ। 2 कप पानी के साथ बरतन में मिलाएँ और उबाल आने दें। आँच धीमी करें, ढक दें और पानी सूखने तक, लगभग 15 मिनट, धीमी आँच पर पकाएँ। ठंडा होने दें।","एक छोटे कटोरे या जार में नीबू का रस, जैतून का तेल, डिजॉन सरसों, लहसुन, हरा धनिया, नमक और काली मिर्च को फेंटकर मिलाएँ।","सलाद तैयार करें। हर बड़े मेसन जार या ऊँचे डिब्बे में, इस क्रम में, डालें: 2–3 बड़े चम्मच विनेग्रेट","थोड़ा सा लाल प्याज़ छिड़कें","1/2 कप काले बीन्स","1/2 कप पका हुआ क्विनोआ","टमाटर, खीरा और शिमला मिर्च, हर एक का 1/4 कप","मुट्ठी भर कटा हुआ पालक"]))
r.append(R(6925969,"डेविल्ड एग्स","डेविल्ड एग्स एक पारंपरिक स्टार्टर हैं। ये किसी भी छुट्टी की पार्टी या सप्ताहांत के मेल-मिलाप के लिए त्वरित और आसान विकल्प हैं।","12","1/2 बड़ा अंडा",
["6 बड़े अंडे","2 बड़े चम्मच + 1 छोटा चम्मच लाइट मेयोनेज़","1/8 छोटा चम्मच सरसों पाउडर","1/8 छोटा चम्मच नमक","1 छोटा चम्मच ताज़ी पिसी काली मिर्च"],
["अंडों को एक छोटे सॉसपैन में इस तरह रखें कि वे उछलें या हिलें नहीं और टूटें नहीं। पानी से ढक दें। उबाल आने दें। तुरंत बंद करके ढक दें। पकना जारी रखने के लिए 15-18 मिनट रहने दें। गरम पानी निकाल दें। छिलके चटकाने के लिए पैन में अंडों को हिलाएँ। ठंडा पानी डालें और रहने दें। (इससे उन्हें छीलना आसान हो जाएगा।)","अंडे छीलें और उन्हें खड़ी लंबाई में आधा काट लें। ज़र्दी निकालें, एक छोटे कटोरे में रखें और काँटे से मसलें। मेयो, सरसों, नमक और काली मिर्च डालें। अंडे की सफ़ेदी में मिश्रण भरें। कटे ग्रेप टमाटर, कटे ज़ैतून, कटी मूली, कटे हरे प्याज़, या कैवियार की एक बूँद या ट्रफ़ल पेस्ट से सजाएँ। (सजावट वैकल्पिक है।)"]))
r.append(R(6926231,"सरल टूना और टमाटर सलाद स्टैक","यह त्वरित, बिना पकाए बनने वाला टूना सलाद मलाईदार मेयोनेज़ को नरम डिब्बाबंद टूना और ताज़े टमाटर के टुकड़ों के साथ मिलाकर हल्का, संतोषजनक एकल-सर्विंग भोजन या स्नैक बनाता है। यह सरल, साफ़-सुथरा और मिनटों में तैयार है।","1","2 टमाटर के टुकड़े और 1/4 कप टूना",
["1/2 कप डिब्बाबंद टूना","1 बड़ा चम्मच मेयोनेज़","2 स्लाइस टमाटर"],
["1/2 कप डिब्बाबंद टूना का पानी निथारें और उसे एक छोटे कटोरे में रखें।","1 बड़ा चम्मच मेयोनेज़ डालें और टूना के समान रूप से लिपटने तक मिलाएँ।","2 टमाटर के टुकड़ों को प्लेट पर सजाएँ।","टूना के मिश्रण को टमाटर के टुकड़ों के ऊपर चम्मच से डालें या उनके साथ परोसें।","तुरंत आनंद लें।"]))
r.append(R(6926509,"टमाटर और आड़ू सलाद","यह सलाद गर्मियों के आख़िर के लिए एकदम सही है जब आड़ू और टमाटर अपने चरम पर होते हैं।","8","लगभग 1 कप",
["3 मध्यम आड़ू (गुठली निकालकर मोटी फाँकों में कटे हुए)","3 मध्यम टमाटर (बड़े टुकड़ों में कटे हुए)","1/2 पिंट चेरी टमाटर (आधे कटे हुए)","1/2 मध्यम लाल प्याज़ (पतला कटा हुआ)","1 बड़ा चम्मच शेरी सिरका","1 बड़ा चम्मच नीबू का रस","1 छोटा चम्मच शहद","2 बड़े चम्मच जैतून का तेल","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप ताज़ा पुदीना"],
["एक बड़े कटोरे में आड़ू, टमाटर, चेरी टमाटर और लाल प्याज़ को मिलाएँ और धीरे से हिलाएँ।","एक छोटे कटोरे या मापने वाले कप में सिरका, नीबू का रस और शहद को फेंटें। फेंटते हुए धीरे-धीरे पतली धार में तेल डालें ताकि वह घुल जाए। नमक और काली मिर्च डालें।","ड्रेसिंग को आड़ू और टमाटर पर डालें और धीरे से मिलाएँ। पुदीने की पत्तियाँ धीरे से मिलाएँ। परोसने के लिए, सलाद को एक बड़ी थाली में पलट दें।"]))
r.append(R(6926611,"बस आड़ू वाले बाउल","ये शानदार \"बाउल\" बहुत प्रभावशाली दिखते हैं, लेकिन इन्हें तैयार करना सचमुच आसान है। आप असल में अपना खुद का फ्लेवर वाला ग्रीक दही बनाएँगे, जो स्वाद और मिठास का स्तर आपके मनमुताबिक बनाने का सबसे अच्छा तरीका है। रसीले आड़ू के ऊपर डालने पर नतीजा बस लाजवाब होता है, ख़ासकर जब फल वसंत या गर्मियों में अपने चरम पर हों। आड़ू को ग्रिल करने से यह मिठाई अनोखी मीठी और धुएँदार बनती है, लेकिन अगर आप और भी जल्दी बनने वाली मिठाई चाहते हैं, तो ग्रिल छोड़ दें और आड़ू को कच्चा रखें।","4","1 बाउल",
["1 कप सादा वसा रहित ग्रीक दही","1 छोटा चम्मच शहद","1/4 छोटा चम्मच शुद्ध वनीला एक्सट्रैक्ट","2 बड़े आड़ू (पूरी तरह पके हुए, आधे कटे हुए, गुठली और डंठल निकाले हुए)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 बड़े चम्मच प्राकृतिक कतले बादाम पैन में भुने हुए, या रोस्टेड पिस्ता","20 पत्ते ताज़ा पुदीना"],
["एक छोटे कटोरे में दही, शहद और वनीला को मिलाएँ।","आड़ू के आधे हिस्सों की कटी हुई तरफ़ पर कुकिंग स्प्रे करें और आड़ू को कटी तरफ़ नीचे करके गरम ग्रिल पर रखें। ग्रिल के निशान बनना शुरू होने और आड़ू के अंदर तक गरम हो जाने तक, 2-3 मिनट ग्रिल करें।","हर आड़ू के आधे हिस्से को कटी तरफ़ ऊपर करके एक छोटी प्लेट पर रखें। हर आधे हिस्से पर दही का मिश्रण, बादाम और पुदीना डालें और परोसें।"]))
r.append(R(6927328,"रोस्टेड सब्ज़ियों वाला क्विनोआ बाउल","यह रोस्टेड सब्ज़ियों वाला क्विनोआ बाउल संतोषजनक आनंद है, जिसे दोपहर या रात के खाने के लिए जोड़ना काफ़ी आसान है। मिश्रण में अपनी पसंदीदा सब्ज़ियाँ डालकर इसे रंगीन बनाएँ। साइट्रस के स्वाद के धमाके के लिए ताज़े नीबू की फाँकों के साथ परोसें।","4","1/2 कप पका क्विनोआ + 3 औंस चिकन + 1 कप सब्ज़ियाँ + 1/2 बड़ा चम्मच फ़ेटा",
["1 कप क्विनोआ (सूखा)","4 कप मिली-जुली, बिना स्टार्च वाली सब्ज़ियाँ (शिमला मिर्च, चेरी टमाटर, ज़ुकीनी, ब्रोकली आदि)","1 मध्यम लाल प्याज़","2 बड़े चम्मच जैतून का तेल","1 छोटा चम्मच सूखा अजवायन","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच फ़ेटा चीज़ (चूरा किया हुआ)","1 मध्यम नीबू (फाँकों में कटा हुआ)","2 साबुत बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (टुकड़ों में कटे हुए)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","एक सॉसपैन में सूखे क्विनोआ को 2 कप पानी के साथ मिलाएँ। उबाल आने दें, फिर आँच धीमी करें। ढक दें और 15 मिनट या क्विनोआ के पकने और पानी सूखने तक धीमी आँच पर पकाएँ।","जब क्विनोआ पक रहा हो, तब कटे हुए चिकन और कटी सब्ज़ियों को बेकिंग शीट पर फैलाएँ।","चिकन और सब्ज़ियों पर जैतून का तेल डालें, सूखा अजवायन, लहसुन पाउडर, नमक और काली मिर्च छिड़कें। समान रूप से लपेटने के लिए मिलाएँ।","चिकन और सब्ज़ियों को पहले से गरम ओवन में लगभग 20–25 मिनट या उनके नरम और हल्का भूरा होने तथा चिकन का आंतरिक तापमान 165 डिग्री F तक पहुँचने तक रोस्ट करें।","पके क्विनोआ और रोस्टेड सब्ज़ियों के मिश्रण को कटोरों में बाँटकर तैयार करें।","ऊपर से चूरा किया फ़ेटा चीज़ डालें और ताज़े नीबू की फाँकों के साथ परोसें।"]))
r.append(R(6927789,"भरपेट नाश्ते का फ्रिटाटा","फ्रिटाटा बची हुई सब्ज़ियों को ख़राब होने से पहले इस्तेमाल करने का बढ़िया तरीका है। जो भी आपके पास हो उसका इस्तेमाल करते हुए, तरह-तरह की बिना स्टार्च वाली सब्ज़ियाँ कार्बोहाइड्रेट की मात्रा कम और पेट भरे होने का एहसास ज़्यादा रखने में मदद करती हैं।","4","4 x 4 इंच का टुकड़ा",
["2 बड़े अंडे","1 कप अंडे का विकल्प","1 कप कम वसा वाला कॉटेज चीज़ (बिना नमक वाला)","1/4 कप सादा वसा रहित ग्रीक दही","2 छोटे चम्मच जैतून का तेल","1/4 कप प्याज़ (कटा हुआ)","1/4 कप लाल शिमला मिर्च (बारीक कटी हुई)","1 फाँक लहसुन (बारीक कटा हुआ)","1 कप बेबी पालक (कटा हुआ)","2 कप केल (कटी हुई, छोटे टुकड़ों में कटी हुई)","3 साबुत आर्टिचोक हार्ट (कटे हुए)","1/4–1/2 छोटा चम्मच कुटी लाल मिर्च के गुच्छे","1/2 छोटा चम्मच सूखी तुलसी","1 बड़ा चम्मच ताज़ी तुलसी (कटी हुई, सजाने के लिए)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। 8 x 8 इंच के बेकिंग पैन पर कुकिंग स्प्रे करें।","एक मध्यम कटोरे में अंडे और अंडे के विकल्प को अच्छी तरह मिलने तक फेंटें। कॉटेज चीज़ और दही डालें और मिलाने के लिए फेंटें। एक तरफ़ रख दें।","एक बड़ी कड़ाही में मध्यम आँच पर जैतून का तेल गरम करें। प्याज़ और लाल शिमला मिर्च डालें और सब्ज़ियों के नरम होना शुरू होने तक 3 मिनट भूनें। लहसुन डालें और 1 मिनट और भूनें।","पालक, केल और ब्रोकली डालकर चलाएँ और पत्तियों के मुरझाने तक, लगभग 2 मिनट पकाएँ। आर्टिचोक, लाल मिर्च के गुच्छे और सूखी तुलसी डालें। आँच से हटाएँ।","सब्ज़ियों को तैयार पैन की तली में फैलाएँ। अंडे और चीज़ का मिश्रण सब्ज़ियों पर डालें और सुनिश्चित करें कि वे अच्छी तरह ढक जाएँ।","पैन को ओवन के बीच में रखें और 40–45 मिनट तक या मिश्रण के जमने और हल्का हिलाने पर न हिलने तक बेक करें।","10 मिनट ठंडा होने दें, फिर 6 टुकड़ों में काट लें। चाहें तो ताज़ी तुलसी से सजाएँ।"]))
r.append(R(6927830,"भूमध्यसागरीय ब्रेकफ़ास्ट पिटा पनीनी","चीज़ वाले अंडों, सन-ड्राइड टमाटर और पालक से भरा साबुत अनाज का पिटा पॉकेट इस पनीनी को स्वादिष्ट और सेहतमंद विकल्प बनाता है।","2","1/2 पिटा + 1 अंडा + 1/2 कप सब्ज़ियाँ",
["1 साबुत साबुत अनाज का पिटा ब्रेड (आधा कटा हुआ)","1 औंस कुकिंग स्प्रे","1/4 कप तरल अंडे का विकल्प","1 बड़ा अंडा","1/4 कप 1% वसा वाला बिना नमक का कॉटेज चीज़","2 बड़े चम्मच तेल में रखे सन-ड्राइड टमाटर (पानी निथारे और कटे हुए)","1/4 छोटा चम्मच सूखी तुलसी","1/4 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच लहसुन पाउडर","1 कप बेबी पालक","2 बड़े चम्मच पार्ट-स्किम मोज़ेरेला (कसा हुआ)"],
["नॉनस्टिक पैन पर कुकिंग स्प्रे करें और मध्यम आँच पर गरम करें। अंडा और अंडे का विकल्प फेंटकर डालें और आंशिक रूप से जमने तक पकाएँ। कॉटेज चीज़, टमाटर, तुलसी, काली मिर्च और लहसुन पाउडर मिलाएँ। अंडों के पकने तक पकाते रहें।","आधे मोज़ेरेला चीज़ को पिटा के आधे हिस्से के अंदर रखें। ऊपर आधी पालक की पत्तियाँ रखें और पिटा में आधा अंडे का मिश्रण भरें। दूसरे पिटा के साथ यही दोहराएँ।","ग्रिल पैन या कड़ाही को मध्यम आँच पर गरम करें। हल्का सा कुकिंग स्प्रे करें और गरम होने पर भरे हुए पिटा को चीज़ वाली तरफ़ नीचे करके पैन पर रखें। भूरा होने और चीज़ के पिघलने तक पकने दें। पिटा को पलटें और दूसरी तरफ़ के भूरा होने तक पकाएँ।"]))
r.append(R(6928135,"साउथवेस्टर्न कोलस्लॉ","साउथवेस्टर्न तड़के वाला ताज़ा कोलस्लॉ। भुने हुए पेकान नाज़ुक कुरकुरापन के साथ सेहतमंद वसा और पोटैशियम, मैग्नीशियम और कैल्शियम देते हैं, जो रक्तचाप के प्रबंधन में सहायक पोषक तत्व हैं।","10","1 कप",
["1/2 कप पेकान (भुने हुए)","1/3 कप जैतून का तेल","2 छोटे चम्मच बिना नमक वाली चिपोटले सीज़निंग","1 बड़ा चम्मच शहद","1 बड़ा चम्मच ताज़ा नीबू का रस","1/4 कप सेब का सिरका","1 साबुत हलापेन्यो मिर्च (बारीक कटी हुई)","3 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (बारीक कटा हुआ)","1 मध्यम लाल शिमला मिर्च (बीज और डंठल निकालकर कटी हुई)","3 मध्यम गाजर (छिली और कसी हुई)","1 हरी पत्तागोभी का गोला (बाहरी पत्ते हटाकर, बारीक कतरी हुई)"],
["एक बड़े सलाद बाउल में पत्तागोभी, गाजर, लाल शिमला मिर्च, हरा प्याज़ और हलापेन्यो मिर्च मिलाएँ और अच्छी तरह मिलाएँ।","एक छोटे कटोरे में सिरका, नीबू का रस, शहद और चिपोटले सीज़निंग को फेंटें। फेंटते हुए पतली धार में जैतून का तेल डालें ताकि वह घुल जाए। ड्रेसिंग को पत्तागोभी के मिश्रण पर डालें और अच्छी तरह मिलाएँ। कोलस्लॉ को भुने हुए पेकान से सजाएँ।"]))
r.append(R(6929227,"लो-कार्ब आर्टिचोक चिकन रैप्स","ये आपके लंचबॉक्स के लिए पहले से तैयार करने लायक बढ़िया चीज़ हैं।","6","1 रैप",
["1 साबुत अंडा","4 साबुत अंडों की सफ़ेदी","1/2 कप स्किम दूध","1/4 कप नारियल का आटा (छना हुआ)","1 साबुत नॉनस्टिक कुकिंग स्प्रे","2 कप चिकन ब्रेस्ट (पका हुआ, रेशे किया हुआ)","1/2 कप आर्टिचोक हार्ट (कटे हुए, पानी निथारे और धोए हुए)","1/4 कप लाल प्याज़ (बारीक कटा हुआ)","2 कप बेबी पालक (कटा हुआ)","1/4 कप इतालवी सलाद ड्रेसिंग (वसा रहित)"],
["अंडा, अंडे की सफ़ेदी और दूध को अच्छी तरह मिलने और हल्का झागदार होने तक फेंटें। नारियल का आटा मिश्रण में छानकर डालें और अच्छी तरह मिलने तक फिर से फेंटें। घोल को कमरे के तापमान पर 15 मिनट रहने दें।","जब रैप का घोल आराम कर रहा हो, तब चिकन, आर्टिचोक हार्ट, लाल प्याज़, बेबी पालक और इतालवी ड्रेसिंग को मिलाएँ। भरावन को ज़रूरत तक फ्रिज में रखें।","10 इंच के नॉनस्टिक सॉते पैन में मध्यम आँच पर कुकिंग स्प्रे करें। पैन को तब तक गरम होने दें जब तक कि पैन की तली में पानी की बूँद चटकने न लगे।","रैप के घोल को दोबारा फेंटें और फिर पैन की तली को पतला ढकने के लिए 1/4 कप घोल डालें (ज़रूरत हो तो पैन की तली ढकने के लिए थोड़ा और डालें)। रैप को किनारे भूरे होना शुरू होने तक पकने दें। स्पैचुला से रैप को पलटें और एक मिनट और पकाते रहें। रैप को प्लेट पर सरकाएँ और 6 \"रैप्स\" या क्रेप बनाने के लिए यही प्रक्रिया जारी रखें। रैप्स को ठंडा होने दें।","चिकन के मिश्रण को हर रैप में बराबर बाँटें (प्रति रैप लगभग 1/2 कप भरावन) और लपेटें।"]))
